// Clunky and error-prone try-finally with nested resources
import java.io.*;

public class CopyUtil {
    private static final int BUFFER_SIZE = 1024;

    static void copy(String src, String dst) throws IOException {
        InputStream in = new FileInputStream(src);
        try {
            OutputStream out = new FileOutputStream(dst);
            try {
                byte[] buf = new byte[BUFFER_SIZE];
                int n;
                while ((n = in.read(buf)) >= 0)
                    out.write(buf, 0, n);
            } finally {
                // If in.read() failed AND out.close() fails,
                // the second exception completely MASKS the first exception!
                out.close();
            }
        } finally {
            in.close();
        }
    }
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        try {
            CopyUtil.copy("source.txt", "target.txt");
        } catch (IOException e) {
            // Stack trace only shows the failure from close(),
            // leaving no clue about the real underlying failure in read()!
            e.printStackTrace();
        }
    }
}

right_code.class:
// Elegant, safe try-with-resources with multiple resources
import java.io.*;

public class CopyUtil {
    private static final int BUFFER_SIZE = 1024;

    static void copy(String src, String dst) throws IOException {
        // Resources are closed in reverse order of declaration
        try (InputStream in = new FileInputStream(src);
             OutputStream out = new FileOutputStream(dst)) {
            byte[] buf = new byte[BUFFER_SIZE];
            int n;
            while ((n = in.read(buf)) >= 0)
                out.write(buf, 0, n);
        }
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        try {
            CopyUtil.copy("source.txt", "target.txt");
        } catch (IOException e) {
            // The actual root exception from read() is preserved and printed.
            // Any exception from close() is attached as a suppressed exception!
            e.printStackTrace();
        }
    }
}
